INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Aktoren immer menschliche Benutzer?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch Systeme sein"}, {"text": "Ja", "correct": false, "because": "Nicht auf Menschen beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spiele ich als Aktor in einem System?', 3, '[{"text": "Interaktion mit dem System", "correct": true, "because": "Beeinflusst Prozesse"}, {"text": "Programmierung", "correct": false, "because": "Entwicklerrolle"}, {"text": "Dokumentation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen von Aktoren gibt es?', 5, '[{"text": "Menschliche Benutzer", "correct": true, "because": "Nutzen das System"}, {"text": "Externe Systeme", "correct": true, "because": "Interagieren automatisch"}, {"text": "Interne Module", "correct": false, "because": "Teil des Systems"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aktoren initiieren Use Cases. b) Sie sind immer Teil des Systems.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktoren sind extern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition eines Aktors?', 4, '[{"text": "Interaktionen", "correct": false, "because": "Kern der Rolle"}, {"text": "Systemgrenzen", "correct": false, "because": "Definiert Aktorstatus"}, {"text": "Firmenlogo", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Aktor mehrere Rollen haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "Kann verschiedene Use Cases starten"}, {"text": "Nein", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entität ist typischerweise ein Aktor?', 3, '[{"text": "Kunde", "correct": true, "because": "Interagiert mit System"}, {"text": "Datenbank", "correct": false, "because": "Systemintern"}, {"text": "Softwaremodul", "correct": false, "because": "Teil des Systems"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Beschreibung eines Aktors?', 5, '[{"text": "Interaktionsart", "correct": true, "because": "Definiert Handlung"}, {"text": "Ziele im System", "correct": true, "because": "Motiviert Interaktion"}, {"text": "Codebasis", "correct": false, "because": "Systemintern"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Aktoren sind in UML-Diagrammen enthalten. b) Sie sind immer physisch präsent. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Können auch Systeme sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Identifikation eines Aktors unwichtig?', 4, '[{"text": "Interaktionspunkte", "correct": false, "because": "Definiert Rolle"}, {"text": "Externer Status", "correct": false, "because": "Unterscheidet vom System"}, {"text": "Programmiersprache", "correct": true, "because": "Technische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Aktor immer aktiv?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch reagieren"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend initiierend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt die Definition von Aktoren?', 4, '[{"text": "Klare Anforderungen", "correct": true, "because": "Zeigt Nutzerbedarf"}, {"text": "Systemgrenzen festlegen", "correct": true, "because": "Unterscheidet extern/intern"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Aktoren nur Menschen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Systeme möglich"}, {"text": "Ja", "correct": false, "because": "Definition breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Aktor-Analyse?', 3, '[{"text": "Interaktionsziele", "correct": true, "because": "Definiert Nutzung"}, {"text": "Technische Details", "correct": false, "because": "Sekundär"}, {"text": "Entwicklungszeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Aktoren stehen außerhalb des Systems. b) Sie sind Teil der Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software ist Systemintern"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine unklare Aktor-Definition?', 5, '[{"text": "Fehlende Anforderungen", "correct": true, "because": "Nutzer unklar"}, {"text": "Verwirrte Entwickler", "correct": true, "because": "Rollen unklar"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Verzögert Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Aktoren unwichtig?', 3, '[{"text": "Interaktionsart", "correct": false, "because": "Definiert Rolle"}, {"text": "Externer Status", "correct": false, "because": "Kernmerkmal"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Systemfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein System ein Aktor sein?', 3, '[{"text": "Ja", "correct": true, "because": "Externe Systeme interagieren"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Aktoren in Use-Case-Diagrammen dargestellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Standard in UML"}, {"text": "Nein", "correct": false, "because": "Typische Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Aktor wähle ich für automatische Prozesse?', 4, '[{"text": "Externes System", "correct": true, "because": "Startet Prozesse"}, {"text": "Menschlicher Benutzer", "correct": false, "because": "Manuell"}, {"text": "Datenbank", "correct": false, "because": "Systemintern"}]');
